"""Offline analysis of LawBench residues. No model calls."""
import json, re, sys
from collections import Counter, defaultdict
from pathlib import Path

sys.path.insert(0, "/workspace/benchmark")
from benchmark.evaluate import load_task  # noqa
import yaml

CONFIG = yaml.safe_load(Path("/workspace/runs/config.yaml").read_text())
RUNS = {
    "N3": "/workspace/runs/354e5e0a025ebb7df470961c775e970ba698f2a3",
    "N4": "/workspace/runs/2e2d9226c1bd9098aec78b9f08fdd3f028ff74a0",
    "N2": "/workspace/runs/57747d4b0c2deb91d13bbff1aabbfd271def0afa",
}


def parse_charges(text):
    text = (text or "").strip()
    m = re.search(r"\[罪名\](.*?)(?:<eoa>|$)", text)
    if m:
        text = m.group(1).strip()
    elif "罪名:" in text:
        text = text.split("罪名:")[-1]
    text = re.sub(r"<eoa>.*", "", text).strip()
    for sep in [";", "；", ",", "，", "、"]:
        if sep in text:
            return {p.strip() for p in text.split(sep) if p.strip()}
    return {text} if text else set()


def load_rows(run):
    rows = []
    for line in Path(run, "results/samples.jsonl").read_text().splitlines():
        row = json.loads(line)
        if row["task"] == "LawBench":
            rows.append(row)
    return rows


def main():
    val = load_task("LawBench", CONFIG, "val")
    memory = json.loads(Path(RUNS["N3"], "LawBench/memory.json").read_text())["examples"]
    mem_answers = set(e["target"] for e in memory)
    counts = Counter(e["target"] for e in memory)
    parts = Counter()
    for a, c in counts.items():
        for p in re.split(r"[;；,，、|.]", a):
            p = p.strip()
            if p:
                parts[p] += c
    part_only = {p: c for p, c in parts.items() if p not in counts}
    print(f"val questions: {len(val)}  memory items: {len(memory)}")
    print(f"distinct memory answers: {len(mem_answers)}  distinct parts: {len(parts)}  part-only: {len(part_only)}")

    # gold coverage by memory
    exact = sum(1 for e in val if e["target"] in mem_answers)
    percharge = 0
    for e in val:
        gold = parse_charges(e["target"])
        if gold and all(g in mem_answers or g in part_only for g in gold):
            percharge += 1
    print(f"val questions whose gold is an exact memory answer: {exact}/{len(val)}")
    print(f"val questions whose every gold charge is in memory (answer or part): {percharge}/{len(val)}")

    for name, run in RUNS.items():
        rows = load_rows(run)
        good = [r for r in rows if r["status"] == "ok"]
        wrong = [r for r in good if not r["was_correct"]]
        comp = Counter()
        missing_buckets = Counter()
        miss_detail = []
        for r in wrong:
            pr = parse_charges(r["prediction"])
            tg = parse_charges(r["target"])
            fn, fp = tg - pr, pr - tg
            if fn and fp:
                comp["both"] += 1
            elif fn:
                comp["subset(only missing)"] += 1
            else:
                comp["superset(only extra)"] += 1
            for g in fn:
                if g in mem_answers:
                    b = "in memory as answer"
                elif g in part_only:
                    b = "in memory as part only"
                else:
                    b = "absent from memory"
                missing_buckets[b] += 1
                miss_detail.append((r["example_index"], r["sample_index"], g, b, sorted(fp)))
        print(f"\n== {name} ({run.split('/')[-1][:8]}) ok={len(good)} wrong={len(wrong)}")
        print("   composition:", dict(comp))
        print("   missing gold charges by memory support:", dict(missing_buckets))
        qmissing = defaultdict(list)
        for ei, si, g, b, fp in miss_detail:
            qmissing[ei].append((g, b))
        print(f"   questions with >=1 missing charge: {len(qmissing)}")
        print(f"   samples whose missing charges are ALL absent from memory: "
              f"{sum(1 for ei, si, g, b, fp in miss_detail if False)}")
    # per-question union analysis: does the union over the 2 samples equal gold?
    rows = load_rows(RUNS["N4"])
    byq = defaultdict(list)
    for r in rows:
